// eta.js (después del cambio)
function estimarHoras(distanciaKm, velocidadKmh) {
  const manejo = distanciaKm / velocidadKmh;
  return manejo > 8 ? manejo + 0.75 : manejo;
}
module.exports = { estimarHoras };

// eta.test.js (las dos pruebas)
test('400 km a 80 km/h son 5 horas', () => {
  assert.strictEqual(estimarHoras(400, 80), 5);
});
test('rutas de más de 8 h de manejo suman 45 min de descanso', () => {
  assert.strictEqual(estimarHoras(800, 80), 10.75);
});
